"""Migrated OPP_MASTER validation rules from legacy opportunity_rules.vrl."""

from decimal import Decimal, InvalidOperation


def _value(row: dict | None, column: str) -> object:
    if row is None:
        return ""
    value = row.get(column, "")
    return "" if value is None else value


def _nvl(value: object, default: object) -> object:
    return default if value is None or value == "" else value


def _number(value: object) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _date_ge(left: object, right: object) -> bool:
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Return all legacy validation failures in rule-file order."""
    errors: list[dict] = []

    amt = _value(record, "AMT")
    stat_cd = _value(record, "STAT_CD")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")
    old_stat_cd = "" if event == "INSERT" else _value(old, "STAT_CD")

    if event in ("INSERT", "UPDATE"):
        if _number(_nvl(amt, 0)) < Decimal(0):
            errors.append(
                {"code": "E3001", "message": "Amount negative", "severity": "BLOCK"}
            )

        if stat_cd == "W" and _number(_nvl(amt, 0)) == Decimal(0):
            errors.append(
                {
                    "code": "E3002",
                    "message": "Won opportunity requires amount",
                    "severity": "BLOCK",
                }
            )

        if stat_cd == "L" and lost_rsn == "":
            errors.append(
                {
                    "code": "E3003",
                    "message": "Lost reason required",
                    "severity": "BLOCK",
                }
            )

        if stat_cd == "W" and close_dt == "00000000":
            errors.append(
                {
                    "code": "E3004",
                    "message": "Won opportunity requires close date",
                    "severity": "BLOCK",
                }
            )

    if event == "UPDATE":
        if old_stat_cd == "W" and stat_cd != "W":
            errors.append(
                {
                    "code": "E3005",
                    "message": "Cannot reopen a won opportunity",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        stage_is_valid = (
            (stat_cd == "P" and _number(stage_pct) == Decimal(10))
            or (stat_cd == "Q" and _number(stage_pct) == Decimal(25))
            or (stat_cd == "N" and _number(stage_pct) == Decimal(60))
            or (stat_cd == "W" and _number(stage_pct) == Decimal(100))
            or (stat_cd == "L" and _number(stage_pct) == Decimal(0))
        )
        if not stage_is_valid:
            errors.append(
                {
                    "code": "E3006",
                    "message": "Stage percent inconsistent with status",
                    "severity": "BLOCK",
                }
            )

    if event == "INSERT":
        if not (close_dt == "00000000" or _date_ge(close_dt, today)):
            errors.append(
                {
                    "code": "E3007",
                    "message": "Close date in past",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return True when one or more validation failures are blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
